-- Migration 017: load player identities, set fact owners, delete confirmed errors
-- Run in Supabase SQL Editor. Steps 0-6 run as one transaction. PURE ASCII (player names in the
-- deletion list are stored as md5 hashes). No temp tables. The check block was run ALONE in a
-- fresh session on a full local copy (live-like setup: pg_trgm in public, unaccent in extensions;
-- 016 + 016b applied; all 225039 facts; the same staging rows).
--
-- Decisions implemented (user, Sept 25 2026):
--  1. Accept the 181 inferred same-name facts; each owned fact records how its owner was found
--     in the new column player_facts.owner_method ('inferred: ...' rows are the Phase 2 review list).
--  2. Same-name facts with no evidence stay unowned (player_id NULL).
--  3. Keep never-played facts EXCEPT delete (a) pre-1961 Washington Senators facts stored as
--     Rangers (710; every player already has the Twins fact) and (b) coaching / managing /
--     front-office stints stored as played_for_team (1306). 3 facts are in both lists and
--     are deleted once: 2013 deletions. Maury Schleicher (Raiders) is NOT deleted; left for review.
--  4. Soccer players matched by Wikipedia article are loaded like everyone else.
--  5. Unmatched names stay unowned.
--
-- Guards (the transaction aborts, changing nothing, if either fails):
--  * staging fingerprints must equal the reviewed payload (verified row-for-row on Sept 25);
--  * all 2013 deletion rows must still match a live fact exactly.

BEGIN;

-- --- 0. BACKUP (RLS on, no browser access) -------------------------------------
CREATE TABLE backup_20260925_player_facts_017 AS SELECT * FROM player_facts;
ALTER TABLE backup_20260925_player_facts_017 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON backup_20260925_player_facts_017 FROM anon, authenticated;

-- --- 1. GUARD: staging is exactly what was reviewed ------------------------------
DO $g$
DECLARE r RECORD;
BEGIN
  SELECT count(*) AS n, md5(string_agg(wikipedia_page_id::text || '|' || wikipedia_title || '|' || coalesce(wikidata_qid, '') || '|' || array_to_string(sports, ',') || '|' || coalesce(sr_nba, '') || '|' || coalesce(sr_mlb, '') || '|' || coalesce(sr_nfl, '') || '|' || coalesce(sr_nhl, ''), chr(10) ORDER BY wikipedia_page_id)) AS h FROM stage_players INTO r;
  -- (count, fingerprint) expected: (77008, 3cfe8771ac02ed4e23838813355460fe)
  IF r.n <> 77008 OR r.h <> '3cfe8771ac02ed4e23838813355460fe' THEN RAISE EXCEPTION '017 guard: stage_players differs from the reviewed payload (n=%, h=%)', r.n, r.h; END IF;
  SELECT count(*) AS n, md5(string_agg(wikipedia_page_id::text || '|' || md5(alias || '|' || kind || '|' || source), chr(10) ORDER BY wikipedia_page_id, md5(alias || '|' || kind || '|' || source) COLLATE "C")) AS h FROM stage_player_aliases INTO r;
  IF r.n <> 138962 OR r.h <> '3282817534316393f92fa17fbc0d1240' THEN RAISE EXCEPTION '017 guard: stage_player_aliases differs from the reviewed payload (n=%, h=%)', r.n, r.h; END IF;
  SELECT count(*) AS n, md5(string_agg(fact_id::text || '|' || wikipedia_page_id::text || '|' || method, chr(10) ORDER BY fact_id)) AS h FROM stage_fact_owners INTO r;
  IF r.n <> 214437 OR r.h <> '3f46a36355e261399bbe30ff20f4f340' THEN RAISE EXCEPTION '017 guard: stage_fact_owners differs from the reviewed payload (n=%, h=%)', r.n, r.h; END IF;
END
$g$;

-- --- 2. DELETION LIST (kept as a record; RLS on) ---------------------------------
CREATE TABLE fact_deletions_017 (
  fact_id          BIGINT PRIMARY KEY,
  sport            TEXT NOT NULL,
  fact_type        TEXT NOT NULL,
  fact_value       TEXT NOT NULL,
  player_name_md5  TEXT NOT NULL,
  reason           TEXT NOT NULL
);
ALTER TABLE fact_deletions_017 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON fact_deletions_017 FROM anon, authenticated;

DO $g$
DECLARE n BIGINT;
BEGIN
  SELECT count(*) INTO n FROM fact_deletions_017 d JOIN player_facts f
    ON f.id = d.fact_id AND f.sport = d.sport AND f.fact_type = d.fact_type AND f.fact_value = d.fact_value
   AND md5(f.player_name) = d.player_name_md5;
  IF n <> 2013 THEN RAISE EXCEPTION '017 guard: only % of 2013 deletion rows still match a live fact', n; END IF;
END
$g$;

-- --- 3. PLAYERS ------------------------------------------------------------------
SELECT wikipedia_page_id, wikipedia_title, wikidata_qid, display_name, sports, first_year, last_year, positions, sr_nba, sr_mlb, sr_nfl, sr_nhl
  FROM stage_players;

-- --- 4. ALIASES (normalized by the live functions) -------------------------------
SELECT p.id, a.alias, normalize_name_exact(a.alias), normalize_name(a.alias), a.kind, a.source, a.curated
  FROM stage_player_aliases a JOIN players p ON p.wikipedia_page_id = a.wikipedia_page_id
ON CONFLICT (player_id, alias_exact) DO NOTHING;

-- --- 5. FACT OWNERS (+ how each owner was determined) ----------------------------
ALTER TABLE player_facts ADD COLUMN IF NOT EXISTS owner_method TEXT;
UPDATE player_facts f
   SET player_id = p.id, owner_method = o.method
  FROM stage_fact_owners o JOIN players p ON p.wikipedia_page_id = o.wikipedia_page_id
 WHERE f.id = o.fact_id;

-- --- 6. DELETE CONFIRMED ERRORS -------------------------------------------------
DELETE FROM player_facts f
 USING fact_deletions_017 d
 WHERE f.id = d.fact_id AND f.sport = d.sport AND f.fact_type = d.fact_type AND f.fact_value = d.fact_value
   AND md5(f.player_name) = d.player_name_md5;

COMMIT;

-- --- 7. CHECKS (run after COMMIT; one row; permanent tables only) ----------------
SELECT
  (SELECT count(*) FROM players)                                                         AS players,
  (SELECT count(*) FROM player_aliases)                                                  AS aliases,
  (SELECT count(*) FROM player_facts)                                                    AS facts_total,
  (SELECT count(*) FROM player_facts WHERE player_id IS NOT NULL)                        AS facts_owned,
  (SELECT count(*) FROM player_facts WHERE player_id IS NULL)                            AS facts_unowned,
  (SELECT count(*) FROM player_facts WHERE owner_method LIKE '%(inferred)')             AS facts_inferred,
  (SELECT count(*) FROM backup_20260925_player_facts_017) - (SELECT count(*) FROM player_facts) AS facts_deleted,
  (SELECT count(*) FROM player_facts f JOIN fact_deletions_017 d ON d.fact_id = f.id)   AS deletions_left,
  (SELECT count(*) FROM player_facts WHERE sport = 'MLB' AND fact_type = 'played_for_team' AND fact_value = 'Rangers') AS mlb_rangers_team_facts,
  (SELECT count(DISTINCT player_id) FROM player_facts WHERE sport = 'MLB' AND player_name IN ('Ken Griffey Jr.', 'Griffey Jr.')) AS griffey_jr_ids,
  (SELECT count(DISTINCT player_id) FROM player_facts WHERE sport = 'MLB' AND player_name IN ('Ken Griffey Sr.', 'Ken Griffey, Sr.')) AS griffey_sr_ids,
  (SELECT count(DISTINCT player_id) FROM player_facts WHERE sport = 'MLB' AND player_name IN ('Ken Griffey Jr.', 'Griffey Jr.', 'Ken Griffey Sr.', 'Ken Griffey, Sr.')) AS griffey_ids_total,
  (SELECT count(DISTINCT player_id) FROM player_facts WHERE sport = 'NBA' AND player_name IN ('Gary Payton', 'Gary Payton II')) AS payton_ids,
  (SELECT count(DISTINCT player_id) FROM player_facts WHERE sport = 'NFL' AND player_name = 'Josh Johnson')   AS nfl_josh_johnson_ids,
  (SELECT count(*) FROM player_facts WHERE sport = 'NFL' AND player_name = 'Josh Johnson' AND player_id IS NULL) AS nfl_josh_johnson_unowned,
  (SELECT count(*) FROM player_facts WHERE sport = 'NFL' AND player_name = 'Maury Schleicher' AND fact_value = 'Raiders') AS schleicher_kept,
  (SELECT count(*) FROM players p WHERE NOT EXISTS (SELECT 1 FROM player_aliases a WHERE a.player_id = p.id)) AS players_without_alias,
  (SELECT count(*) FROM players p WHERE NOT EXISTS (SELECT 1 FROM player_facts f WHERE f.player_id = p.id)) AS players_without_facts,
  (SELECT bool_and(relrowsecurity) FROM pg_class WHERE relname IN ('backup_20260925_player_facts_017', 'fact_deletions_017', 'players', 'player_aliases')) AS rls_on,
  (SELECT count(*) FROM information_schema.role_table_grants
    WHERE table_name IN ('backup_20260925_player_facts_017', 'fact_deletions_017', 'players', 'player_aliases')
      AND grantee IN ('anon', 'authenticated'))                                          AS browser_grants;
-- EXPECTED: players 77008, aliases 138962, facts_total 223026, facts_owned 212424, facts_unowned 10602, facts_inferred 181, facts_deleted 2013, deletions_left 0, mlb_rangers_team_facts 1422, griffey_jr_ids 1, griffey_sr_ids 1, griffey_ids_total 2, payton_ids 2, nfl_josh_johnson_ids 2, nfl_josh_johnson_unowned 1, schleicher_kept 1, players_without_alias 0, players_without_facts 2, rls_on true, browser_grants 0

